// Meta verifica el webhook con hub.challenge
const q = $input.first().json.query;
if (q['hub.verify_token'] !== $env.INMATH_WHATSAPP_VERIFY_TOKEN) {
  throw new Error('Verify token inválido');
}
return [{ json: { challenge: q['hub.challenge'] } }];

// Extrae los mensajes de texto del payload de Meta (ignora estados de entrega)
const salida = [];
for (const entry of $input.first().json.body.entry ?? []) {
  for (const change of entry.changes ?? []) {
    const v = change.value ?? {};
    const contacto = (v.contacts ?? [])[0];
    for (const m of v.messages ?? []) {
      if (m.type !== 'text' && m.type !== 'interactive') continue;
      salida.push({ json: {
        telefono_whatsapp: m.from,
        contenido: m.type === 'text' ? m.text.body : (m.interactive?.button_reply?.title ?? m.interactive?.list_reply?.title ?? ''),
        wa_message_id: m.id,
        nombre: contacto?.profile?.name ?? null,
        tipo: m.type === 'text' ? 'texto' : 'interactivo'
      }});
    }
  }
}
return salida;

// Una salida por cada respuesta del bot; conserva el teléfono destino
const r = $input.first().json;
const tel = $('Extraer mensajes').first().json.telefono_whatsapp;
return (r.respuestas ?? []).map(texto => ({ json: { telefono: tel, texto, accion: r.accion, prospecto_id: r.prospecto_id } }));
